// src/cli/output.ts
function formatStatus(status) {
  const lines = [...status.summaryLines];
  for (const t2 of status.transfers) {
    const pct = t2.total !== void 0 && t2.total > 0 ? ` ${String(Math.round(t2.bytes / t2.total * 100))}%` : "";
    lines.push(`  ${t2.kind === "upload" ? "^" : "v"} ${t2.relPath}${pct} (${formatBytes(t2.speed)}/s)`);
  }
  return lines;
}
function formatBytes(n2) {
  if (n2 < 1024) return `${String(Math.round(n2))} B`;
  if (n2 < 1024 * 1024) return `${(n2 / 1024).toFixed(1)} KiB`;
  if (n2 < 1024 * 1024 * 1024) return `${(n2 / 1024 / 1024).toFixed(1)} MiB`;
  return `${(n2 / 1024 / 1024 / 1024).toFixed(2)} GiB`;
}
function formatTable(rows) {
  const widths = [];
  for (const r2 of rows) r2.forEach((c2, i3) => widths[i3] = Math.max(widths[i3] ?? 0, c2.length));
  return rows.map((r2) => r2.map((c2, i3) => c2.padEnd(widths[i3] ?? 0)).join("  ").trimEnd());
}

